<?php
declare(strict_types=1);

require_once __DIR__ . '/../includes/order-helpers.php';
require_auth();

$user = current_user();
$userId = (int) $user['id'];
$recentOrders = user_orders($userId, 3);
$favoriteCount = (int) (db_value('SELECT COUNT(*) FROM favorites WHERE user_id = ?', [$userId]) ?? 0);
$activeApplications = (int) (db_value("SELECT COUNT(*) FROM adoption_applications WHERE user_id = ? AND status NOT IN ('REJECTED', 'ADOPTION COMPLETED')", [$userId]) ?? 0);
$pendingApplications = (int) (db_value("SELECT COUNT(*) FROM adoption_applications WHERE user_id = ? AND status IN ('SUBMITTED', 'UNDER REVIEW', 'INTERVIEW')", [$userId]) ?? 0);
$notificationCount = unread_notification_count();
$recentApplications = db_all('SELECT a.*, p.name AS pet_name, p.breed, p.image FROM adoption_applications a JOIN pets p ON p.id = a.pet_id WHERE a.user_id = ? ORDER BY a.updated_at DESC LIMIT 3', [$userId]);
$recentPets = db_all('SELECT p.*, 1 AS is_favorite FROM pets p JOIN favorites f ON f.pet_id = p.id WHERE f.user_id = ? ORDER BY f.created_at DESC LIMIT 3', [$userId]);
$notifications = db_all('SELECT * FROM notifications WHERE user_id = ? ORDER BY created_at DESC LIMIT 3', [$userId]);
$userSection = 'dashboard';
$pageTitle = 'My dashboard';
$bodyClass = 'dashboard-page';
require __DIR__ . '/../includes/header.php';
